<script setup lang="ts">
import{nextTick,onBeforeUnmount,watch,ref}from'vue';interface Props{modelValue?:boolean;title?:string;description?:string;closeOnEscape?:boolean;closeOnBackdrop?:boolean;dismissLabel?:string};const props=withDefaults(defineProps<Props>(),{modelValue:false,closeOnEscape:true,closeOnBackdrop:true,dismissLabel:'Close dialog'});const emit=defineEmits<{'update:modelValue':[value:boolean];open:[];close:[]}>();const panel=ref<HTMLElement>();let previous:HTMLElement|null=null
function close(){emit('update:modelValue',false);emit('close')};function onDocumentKey(event:KeyboardEvent){if(!props.modelValue)return;if(event.key==='Escape'&&props.closeOnEscape){event.preventDefault();close()}if(event.key==='Tab'&&panel.value){const focusable=[...panel.value.querySelectorAll<HTMLElement>('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.hasAttribute('disabled'));if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(!first||!last)return;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}}
watch(()=>props.modelValue,async value=>{if(value){previous=document.activeElement as HTMLElement;document.addEventListener('keydown',onDocumentKey);await nextTick();panel.value?.querySelector<HTMLElement>('[autofocus],button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')?.focus();emit('open')}else{document.removeEventListener('keydown',onDocumentKey);previous?.focus()}});onBeforeUnmount(()=>document.removeEventListener('keydown',onDocumentKey))
</script>
<template><div v-if="modelValue" class="uv-dialog__backdrop" @mousedown.self="closeOnBackdrop&&close()"><section ref="panel" class="uv-dialog" role="dialog" aria-modal="true" :aria-label="title||'Dialog'" :aria-describedby="description?'uv-dialog-description':undefined"><header class="uv-dialog__header"><div><h2 v-if="title">{{title}}</h2><p v-if="description" id="uv-dialog-description">{{description}}</p></div><button type="button" :aria-label="dismissLabel" @click="close">×</button></header><div class="uv-dialog__body"><slot/></div><footer v-if="$slots.footer" class="uv-dialog__footer"><slot name="footer" :close="close"/></footer></section></div></template>
<style>.uv-dialog__backdrop{position:fixed;z-index:1000;inset:0;display:grid;place-items:center;padding:1rem;background:var(--uv-color-overlay,rgb(15 23 42/.58));font-family:var(--uv-font-sans,system-ui,sans-serif)}.uv-dialog{width:min(560px,100%);max-height:min(80vh,760px);overflow:auto;border:1px solid var(--uv-color-border,#dbe3ef);border-radius:var(--uv-radius-xl,1.25rem);background:var(--uv-color-surface,#fff);color:var(--uv-color-text,#0f172a);box-shadow:var(--uv-shadow-md)}.uv-dialog__header{display:flex;justify-content:space-between;gap:1rem;padding:1.2rem 1.3rem;border-bottom:1px solid var(--uv-color-border,#dbe3ef)}.uv-dialog__header h2,.uv-dialog__header p{margin:0}.uv-dialog__header p{color:var(--uv-color-text-muted,#64748b);font-size:.85rem}.uv-dialog__header button{display:grid;place-items:center;width:2rem;height:2rem;border:0;border-radius:.45rem;background:transparent;color:inherit;font-size:1.4rem}.uv-dialog__header button:focus-visible{outline:0;box-shadow:var(--uv-focus-ring)}.uv-dialog__body{padding:1.3rem}.uv-dialog__footer{display:flex;justify-content:flex-end;gap:.7rem;padding:1rem 1.3rem;border-top:1px solid var(--uv-color-border,#dbe3ef)}</style>
